/**
 * Branded identifiers. Every id that crosses a boundary has its own brand so a
 * `ProjectId` can't be passed where a `MessageId` is expected.
 *
 * Ids are opaque strings generated by the API unless noted. Brands are
 * type-only: decoding checks the string shape, not where it came from.
 */
import { Schema } from "effect"

const opaque = Schema.NonEmptyString.check(Schema.isMaxLength(128))

/**
 * Prefixes the API puts on the ids it generates (`prj_…`, `msg_…`), so ids
 * read well in logs and in the agent's prompts, where it copies them into
 * `dream` commands. Decoding doesn't enforce them.
 */
export const IdPrefix = {
  user: "usr",
  project: "prj",
  message: "msg",
  media: "med",
  event: "evt",
  wake: "wak",
  integration: "int",
  modelConnection: "mcn",
  browserSession: "brs",
  link: "lnk"
} as const

export const UserId = opaque.pipe(Schema.brand("UserId"))
export type UserId = typeof UserId.Type

export const ProjectId = opaque.pipe(Schema.brand("ProjectId"))
export type ProjectId = typeof ProjectId.Type

export const MessageId = opaque.pipe(Schema.brand("MessageId"))
export type MessageId = typeof MessageId.Type

export const MediaId = opaque.pipe(Schema.brand("MediaId"))
export type MediaId = typeof MediaId.Type

export const EventId = opaque.pipe(Schema.brand("EventId"))
export type EventId = typeof EventId.Type

export const WakeId = opaque.pipe(Schema.brand("WakeId"))
export type WakeId = typeof WakeId.Type

export const IntegrationId = opaque.pipe(Schema.brand("IntegrationId"))
export type IntegrationId = typeof IntegrationId.Type

export const ModelConnectionId = opaque.pipe(Schema.brand("ModelConnectionId"))
export type ModelConnectionId = typeof ModelConnectionId.Type

export const BrowserSessionId = opaque.pipe(Schema.brand("BrowserSessionId"))
export type BrowserSessionId = typeof BrowserSessionId.Type

export const LinkId = opaque.pipe(Schema.brand("LinkId"))
export type LinkId = typeof LinkId.Type

/** Client-generated UUID, kept in SecureStore for the life of the install. */
export const DeviceId = Schema.String.check(Schema.isUUID()).pipe(Schema.brand("DeviceId"))
export type DeviceId = typeof DeviceId.Type

/**
 * Client-generated UUID that makes a write safe to retry: the phone sends the
 * same one again when it retries a request whose response it never got, and
 * the API returns what the first attempt created instead of creating it twice.
 * A new request (other text, another idea) gets a new one.
 */
export const RequestId = Schema.String.check(Schema.isUUID()).pipe(Schema.brand("RequestId"))
export type RequestId = typeof RequestId.Type

/**
 * A UUID that the Worker sends as the `apns-id` header, so the app can later
 * remove that delivered notification by identifier when it is withdrawn.
 */
export const NotificationId = Schema.String.check(Schema.isUUID()).pipe(Schema.brand("NotificationId"))
export type NotificationId = typeof NotificationId.Type
